const items = $input.all();
const alerts = items.filter(i => i.json && i.json.id);
if (alerts.length === 0) return [];
if (alerts.length > 50) {
  return [{ json: { _queue_saturated: true, count: alerts.length } }];
}
return alerts.slice(0, 5).map(i => ({ json: i.json }));

const item = $input.first().json;
// Reject error bubbles (Continue on Fail upstream)
if (item.error) return [];
// Reject queue-saturation sentinel
if (item._queue_saturated) return [];
// Reject anything that is not a real pending alert
// (e.g. Supabase Mark Done response loops back with status='done')
const alertId = Number(item.id);
if (!alertId || !item.rule_id || item.status !== 'pending') return [];
const sd = $getWorkflowStaticData('global');
sd.enrichedIocs = [];
sd.currentAlert = item;
return [{ json: item }];

const sd    = $getWorkflowStaticData('global');
const alert = sd.currentAlert || {};
if (!alert.id) return [];
const level  = parseInt(alert.rule_level ?? 0, 10);
const prefix = level >= 12 ? '[CRITICAL]' : level >= 8 ? '[HIGH]' : level >= 5 ? '[MEDIUM]' : '[LOW]';
const title  = alert.rule_desc || `Rule ${alert.rule_id || 'unknown'}`;
const sep    = '───────────────────────────';
const ts     = new Date().toISOString().replace('T',' ').slice(0,19) + ' UTC';
const lines  = [
  `${prefix} ${title}`, sep,
  `rule_id   : ${alert.rule_id   || 'n/a'}`,
  `agent     : ${alert.agent_name || 'n/a'} (${alert.agent_ip || 'n/a'})`,
  alert.username ? `user      : ${alert.username}` : null,
  alert.command  ? `command   : ${alert.command}`  : null,
  '', 'no external ioc detected', '',
  `${ts} · mini-soc/wazuh`,
].filter(l => l !== null);
return [{ json: { text: '```\n' + lines.join('\n') + '\n```', alert_id: alert.id } }];

const sd    = $getWorkflowStaticData('global');
const alert = sd.currentAlert || {};
if (!alert.id) return [];
let iocs = [];
if (Array.isArray(alert.iocs)) {
  iocs = alert.iocs;
} else if (typeof alert.iocs === 'string' && alert.iocs.trim()) {
  try { iocs = JSON.parse(alert.iocs); } catch { iocs = []; }
}
const valid = iocs.filter(ioc => ioc && ioc.value && ioc.type);
if (valid.length === 0) return [];
return valid.map(ioc => ({
  json: { ...alert, ioc_value: String(ioc.value), ioc_type: String(ioc.type).toLowerCase() }
}));

const sd  = $getWorkflowStaticData('global');
const now  = Date.now();
const last = sd.lastVTCallMs || 0;
const wait = 15000 - (now - last);
if (wait > 0) await new Promise(r => setTimeout(r, wait));
sd.lastVTCallMs = Date.now();
const iocValue = $json.ioc_value || '';
const iocType  = $json.ioc_type  || 'unknown';
sd.currentIoc  = { value: iocValue, type: iocType };
return [{ json: $input.first().json }];

const sd = $getWorkflowStaticData('global');
const vtItems    = $items('HTTP — VT IP');
const abuseItems = $items('HTTP — AbuseIPDB');
const vt    = vtItems[0]?.json    || {};
const abuse = abuseItems[0]?.json || {};
const vtError = !!vt.error;
const stats     = vt.data?.attributes?.last_analysis_stats || {};
const malicious = Number(stats.malicious) || 0;
const total     = Object.values(stats).reduce((a, b) => a + (Number(b) || 0), 0);
const abusePct  = Number(abuse.data?.abuseConfidenceScore) || 0;
let verdict = vtError ? 'UNKNOWN' : 'CLEAN';
if (!vtError) {
  if (malicious > 5 || abusePct > 50) verdict = 'MALICIOUS';
  else if (malicious > 0 || abusePct > 10) verdict = 'SUSPICIOUS';
}
if (!sd.enrichedIocs) sd.enrichedIocs = [];
sd.enrichedIocs.push({
  value: sd.currentIoc?.value || '?', type: 'ip',
  vt_malicious: malicious, vt_total: total,
  abuse_confidence: abusePct, verdict,
  vt_error: vtError || undefined,
});
return [{ json: { loop_continue: true } }];

const sd = $getWorkflowStaticData('global');
const vtItems = $items('HTTP — VT Hash');
const mwItems = $items('HTTP — MalwareBazaar');
const vt  = vtItems[0]?.json || {};
const mw  = mwItems[0]?.json || {};
const vtError = !!vt.error;
const stats     = vt.data?.attributes?.last_analysis_stats || {};
const malicious = Number(stats.malicious) || 0;
const total     = Object.values(stats).reduce((a, b) => a + (Number(b) || 0), 0);
const mwFound   = mw.query_status === 'ok' && Array.isArray(mw.data) && mw.data.length > 0;
let verdict = vtError ? 'UNKNOWN' : 'CLEAN';
if (!vtError) {
  if (malicious > 5 || mwFound) verdict = 'MALICIOUS';
  else if (malicious > 0) verdict = 'SUSPICIOUS';
}
if (!sd.enrichedIocs) sd.enrichedIocs = [];
sd.enrichedIocs.push({
  value: sd.currentIoc?.value || '?', type: 'hash',
  vt_malicious: malicious, vt_total: total,
  mwbazaar_found: mwFound, verdict,
  vt_error: vtError || undefined,
});
return [{ json: { loop_continue: true } }];

const sd = $getWorkflowStaticData('global');
const vtItems = $items('HTTP — VT Domain');
const vt = vtItems[0]?.json || {};
const vtError = !!vt.error;
const stats     = vt.data?.attributes?.last_analysis_stats || {};
const malicious = Number(stats.malicious) || 0;
const total     = Object.values(stats).reduce((a, b) => a + (Number(b) || 0), 0);
let verdict = vtError ? 'UNKNOWN' : 'CLEAN';
if (!vtError) {
  if (malicious > 5) verdict = 'MALICIOUS';
  else if (malicious > 0) verdict = 'SUSPICIOUS';
}
if (!sd.enrichedIocs) sd.enrichedIocs = [];
sd.enrichedIocs.push({
  value: sd.currentIoc?.value || '?', type: 'domain',
  vt_malicious: malicious, vt_total: total, verdict,
  vt_error: vtError || undefined,
});
return [{ json: { loop_continue: true } }];

const sd = $getWorkflowStaticData('global');
const alert = sd.currentAlert || {};
const iocs  = sd.enrichedIocs || [];
const av    = sd.aiVerdict || null;
const aiErr = sd.aiError   || null;
sd.enrichedIocs = [];
sd.currentAlert = null;
sd.aiVerdict    = null;
sd.aiError      = null;
// Safety: if alert has no id, bail
if (!alert.id) return [{ json: { _skipped: true } }];
const level  = parseInt(alert.rule_level ?? 0, 10);
const prefix = level >= 12 ? '[CRITICAL]' : level >= 8 ? '[HIGH]' : level >= 5 ? '[MEDIUM]' : '[LOW]';
const title  = alert.rule_desc || `Rule ${alert.rule_id || 'unknown'}`;
const sep    = '───────────────────────────';
const ts     = new Date().toISOString().replace('T',' ').slice(0,19) + ' UTC';
let iocBlock = iocs.length === 0 ? '\nno external ioc detected' : '\nioc enrichment';
for (const ioc of iocs) {
  iocBlock += `\n  ${ioc.value}`;
  const errNote = ioc.vt_error ? ' (vt unavailable)' : '';
  if (ioc.type === 'ip') {
    iocBlock += `\n    vt       : ${ioc.vt_malicious}/${ioc.vt_total}  ← ${ioc.verdict}${errNote}`;
    if (ioc.abuse_confidence !== undefined) iocBlock += `\n    abuse    : ${ioc.abuse_confidence}%`;
  } else if (ioc.type === 'hash') {
    iocBlock += `\n    vt       : ${ioc.vt_malicious}/${ioc.vt_total}  ← ${ioc.verdict}${errNote}`;
    if (ioc.mwbazaar_found) iocBlock += `\n    mwbazaar : known malware`;
  } else if (ioc.type === 'domain') {
    iocBlock += `\n    vt       : ${ioc.vt_malicious}/${ioc.vt_total}  ← ${ioc.verdict}${errNote}`;
  }
}
// AI verdict block — success / error / silent skip
let aiBlock = null;
if (av && typeof av === 'object') {
  aiBlock = [
    '',
    '── ai verdict ────────────────────────',
    `  severity   : ${av.severity || '?'}`,
    `  verdict    : ${av.verdict || '?'}`,
    `  reason     : ${av.reason || '?'}`,
    `  action     : ${av.suggested_action || '?'}`,
    `  confidence : ${av.confidence || '?'}`,
  ].join('\n');
} else if (aiErr) {
  aiBlock = '\n── ai verdict ────────────────────────\n  status : ⚠ ai error — ' + aiErr;
}
const lines = [
  `${prefix} ${title}`, sep,
  `rule_id   : ${alert.rule_id   || 'n/a'}`,
  `agent     : ${alert.agent_name || 'n/a'} (${alert.agent_ip || 'n/a'})`,
  alert.username ? `user      : ${alert.username}` : null,
  alert.command  ? `command   : ${alert.command}`  : null,
  iocBlock,
  aiBlock,
  '',
  `${ts} · mini-soc/wazuh`,
].filter(l => l !== null);
return [{ json: { text: '```\n' + lines.join('\n') + '\n```', alert_id: alert.id } }];

const sd = $getWorkflowStaticData('global');
const alert = sd.currentAlert || {};
const iocs = sd.enrichedIocs || [];
const iocSummary = iocs
  .filter(ioc => ioc && ioc.type && ioc.value)
  .map(ioc => {
    const t = String(ioc.type).toLowerCase();
    let s = `- ${t.toUpperCase()} ${ioc.value}: verdict=${ioc.verdict || 'UNKNOWN'}`;
    if (t === 'ip')     s += `, VT=${ioc.vt_malicious ?? 'N/A'}/${ioc.vt_total ?? 'N/A'}, AbuseIPDB=${ioc.abuse_confidence ?? 'N/A'}%`;
    if (t === 'hash')   s += `, VT=${ioc.vt_malicious ?? 'N/A'}/${ioc.vt_total ?? 'N/A'}, MalwareBazaar=${ioc.mwbazaar_found ? 'found' : 'not found'}`;
    if (t === 'domain') s += `, VT=${ioc.vt_malicious ?? 'N/A'}/${ioc.vt_total ?? 'N/A'}`;
    return s;
  }).join('\n') || 'no IOCs detected';
const text = [
  `Wazuh Alert: ${alert.rule_desc || 'unknown'} (rule_id: ${alert.rule_id || 'n/a'}, level: ${alert.rule_level || 0})`,
  `Agent: ${alert.agent_name || 'n/a'} (${alert.agent_ip || 'n/a'})`,
  alert.username ? `User: ${alert.username}` : null,
  alert.command  ? `Command: ${alert.command}` : null,
  '', 'IOCs analyzed:', iocSummary,
  '',
  'Output ONLY a JSON object with these exact fields, no markdown, no code fences, no prose:',
  '{"severity":"critical|high|medium|low","verdict":"one sentence","reason":"evidence from IOCs","suggested_action":"one concrete action","confidence":"high|medium|low"}',
].filter(l => l !== null).join('\n');
return [{ json: { ai_input: text } }];

const sd = $getWorkflowStaticData('global');
const input = $input.first().json;

// 1. AI Agent failed (continueOnFail routes error here)
if (input.error) {
  sd.aiVerdict = null;
  sd.aiError   = String(input.error.message || 'AI Agent failed').slice(0, 100);
  return [{ json: { loop_continue: true } }];
}

// 2. Strip markdown code fences
const raw = String(input?.output || '');
const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();

// 3. Parse — attempt 1: direct, attempt 2: extract first {severity} block
let verdict = null;
try {
  verdict = JSON.parse(cleaned);
} catch {
  const match = cleaned.match(/\{[^{}]*"severity"[^{}]*\}/s);
  if (match) { try { verdict = JSON.parse(match[0]); } catch {} }
}

// 4. Validate fields and enum values
const REQUIRED    = ['severity', 'verdict', 'reason', 'suggested_action', 'confidence'];
const SEVERITIES  = ['critical', 'high', 'medium', 'low'];
const CONFIDENCES = ['high', 'medium', 'low'];

if (verdict && typeof verdict === 'object') {
  const missing = REQUIRED.filter(k => !verdict[k]);
  verdict.severity   = String(verdict.severity   || '').toLowerCase();
  verdict.confidence = String(verdict.confidence || '').toLowerCase();
  if (!SEVERITIES.includes(verdict.severity))   verdict.severity   = 'low';
  if (!CONFIDENCES.includes(verdict.confidence)) verdict.confidence = 'low';
  if (missing.length > 2) {
    sd.aiError = `AI verdict incomplete (missing: ${missing.join(', ')})`;
    verdict = null;
  }
}

sd.aiVerdict = verdict || null;
if (!verdict && !sd.aiError) sd.aiError = 'AI returned unparseable output';
return [{ json: { loop_continue: true } }];
